    long long n;
    cin >> n;
    vector<long long> a(n);
    for (int i = 0; i < n; i++) cin >> a[i];
    vector<long long> b(n);
    for (int i = 0; i < n; i++) cin >> b[i];

    sort(a.begin(), a.end());
    sort(b.begin(), b.end());
    long long wins = 0;
    for (long long x : a) {
        if (x > b[wins]) wins++;
    }
    cout << wins << "\n";

    return 0;
